// src/js/Chat/PrivateChat.helpers.js

import { emojify } from "../Chat/Emoji/EmojiParser.js";

export function linkifyAndEmojify(text) {
    if (!text) return "";

    // Detecta URLs
    const urlRegex = /(https?:\/\/[^\s]+)/gi;

    // Adiciona links clicáveis
    const html = text.replace(urlRegex, (url) => {
        return `<a 
      href="${url}" 
      target="_blank" 
      rel="noopener noreferrer"
      style="color:#0b66ff;text-decoration:underline;"
    >${url}</a>`;
    });

    // Aplica twemoji por último
    return emojify(html);
}

export function makeRoomId(a, b) {
    return [a, b].sort().join("_");
}

export function formatTime(ts) {
    if (!ts) return "";
    const d = ts?.toDate ? ts.toDate() : new Date(ts);
    return d.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
}

/*
 getMessageUrl: aceita string ou objeto {publicUrl, path, url}
 */
export function getMessageUrl(m) {
    if (!m) return "";
    if (typeof m === "string") return m;
    if (typeof m === "object") {
        return m.publicUrl || m.publicURL || m.public_url || m.url || "";
    }
    return "";
}

export function linkifyText(text, linkClassName = "") {
    if (!text) return text;
    const urlRegex = /https?:\/\/[^\s/$.?#].[^\s]*/gi;
    const parts = [];
    let lastIndex = 0;
    let match;
    while ((match = urlRegex.exec(text)) !== null) {
        const idx = match.index;
        if (idx > lastIndex) parts.push(text.substring(lastIndex, idx));
        const url = match[0];
        parts.push({ url });
        lastIndex = idx + url.length;
    }
    if (lastIndex < text.length) parts.push(text.substring(lastIndex));

    return parts.map((p, i) => {
        if (typeof p === "string") return p;
        return (
            <a
                key={`lnk-${i}`}
                href={p.url}
                target="_blank"
                rel="noopener noreferrer"
                className={linkClassName}
                style={{ color: "#0b66ff", textDecoration: "underline" }}
            >
                {p.url}
            </a>
        );
    });
}
